refentry.refsect1:
&reftitle.description;
boolis_numeric mixedvalue
Determina se la variabile data è un numero o una stringa numerica.

&reftitle.changelog;





    &Version;
    &Description;





    8.0.0

     Le stringhe numeriche che terminano con uno spazio ("42 ")
     ora restituiscono &true;. In precedenza veniva restituito &false;.

  &reftitle.examples;



    Esempi di is_numeric


<?php
$tests = array(
    "42",
    1337,
    0x539,
    02471,
    0b10100111001,
    1337e0,
    "0x539",
    "02471",
    "0b10100111001",
    "1337e0",
    "not numeric",
    array(),
    9.1,
    null,
    '',
);

foreach ($tests as $element) {
    if (is_numeric($element)) {
        echo var_export($element, true) . " is numeric", PHP_EOL;
    } else {
        echo var_export($element, true) . " is NOT numeric", PHP_EOL;
    }
}
?>


    &example.outputs;


'42' is numeric
1337 is numeric
1337 is numeric
1337 is numeric
1337 is numeric
1337.0 is numeric
'0x539' is NOT numeric
'02471' is numeric
'0b10100111001' is NOT numeric
'1337e0' is numeric
'not numeric' is NOT numeric
array (
) is NOT numeric
9.1 is numeric
NULL is NOT numeric
'' is NOT numeric








    is_numeric con spazi


<?php
$tests = [
    " 42",
    "42 ",
    "\u{A0}9001", // spazio non separabile
    "9001\u{A0}", // spazio non separabile
];

foreach ($tests as $element) {
    if (is_numeric($element)) {
        echo var_export($element, true) . " is numeric", PHP_EOL;
    } else {
        echo var_export($element, true) . " is NOT numeric", PHP_EOL;
    }
}
?>


    &example.outputs.8;


' 42' is numeric
'42 ' is numeric
' 9001' is NOT numeric
'9001 ' is NOT numeric


    &example.outputs.7;


' 42' is numeric
'42 ' is NOT numeric
' 9001' is NOT numeric
'9001 ' is NOT numeric
